import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { CategorieService } from './categorie.service';

@Component({
  selector: 'app-categorie',
  templateUrl: './categorie.component.html',
  styleUrls: ['./categorie.component.css'],
})
export class CategorieComponent implements OnInit {
  categorias: any[] = [];
  exibirFormulario = false;
  exibirModal = false; // Controle para exibir o modal de confirmação
  categoriaForm: FormGroup;
  actionType: string = '';
  constructor(
    private categorieService: CategorieService,
    private fb: FormBuilder
  ) {
    this.categoriaForm = this.fb.group({
      name: ['', [Validators.required, Validators.maxLength(50)]],
      description: ['', Validators.maxLength(200)],
    });
  }

  ngOnInit(): void {
    this.listarCategorias();
  }

  listarCategorias(): void {
    this.categorieService.findAll().subscribe((res: any) => {
      console.log('categorias', res);
      this.categorias = res.result;
    });
  }

  toggleFormulario(): void {
    this.exibirFormulario = !this.exibirFormulario;
    if (!this.exibirFormulario) {
      this.categoriaForm.reset();
    }
  }

  adicionarCategoria(): void {
    if (this.categoriaForm.valid) {
      this.actionType = 'adicionar';
      this.toggleModal(); // Exibe o modal antes de salvar
    }
  }

  excluirCategoria(id: number): void {
    console.log('1', id);

    this.categorieService.delete(id.toString()).subscribe(() => {
      this.listarCategorias();
      this.actionType = 'excluir';
      this.toggleModal();
    });
  }

  toggleModal(): void {
    this.exibirModal = !this.exibirModal;
  }

  confirmarAdicao(): void {
    // Salva a categoria após a confirmação
    this.categorieService.create(this.categoriaForm.value).subscribe(() => {
      this.listarCategorias();
      this.toggleFormulario();
      this.toggleModal(); // Fecha o modal
    });
  }

  cancelarAdicao(): void {
    console.log('Ação cancelada.');
    this.toggleModal(); // Fecha o modal sem salvar
  }
}
<app-page-body>
  <h2>Categorias</h2>

  <button (click)="toggleFormulario()" class="btn-novo-produto">
    Nova Categoria
  </button>

  <div *ngIf="exibirFormulario" class="modal-overlay">
    <div class="modal-content">
      <span class="close-btn" (click)="toggleFormulario()">&times;</span>
      <h2>Cadastrar Categoria</h2>
      <form [formGroup]="categoriaForm" (ngSubmit)="adicionarCategoria()">
        <label for="nome">Nome:</label>
        <input id="nome" formControlName="name" required />
        <button type="submit" [disabled]="categoriaForm.invalid">
          Cadastrar
        </button>
      </form>
    </div>
  </div>

  <table>
    <thead>
      <tr>
        <th>Id</th>
        <th>Nome</th>
        <th>Ações</th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let categoria of categorias">
        <td>{{ categoria.id }}</td>
        <td>{{ categoria.name }}</td>
        <td>
          <button class="btn-icon delete-btn" (click)="excluirCategoria(categoria.id)">
            <i class="fa fa-trash"></i>
          </button>
        </td>
      </tr>
    </tbody>
  </table>

  <p *ngIf="categorias.length === 0">Nenhuma categoria cadastrada.</p>

  <!-- Modal de confirmação -->
  <app-modal
    [visible]="exibirModal"
    title="Confirmação"
    message="Deseja realmente{{actionType}} esta categoria?"
    (onConfirm)="confirmarAdicao()"
    (onCancel)="cancelarAdicao()"
  ></app-modal>
</app-page-body>
